}
__device__ __forceinline__ float gelu_erf(float z) { return 0.5f * z * (1.f + erff(z * 0.70710678118654752f)); }
__device__ __forceinline__ uint32_t h2u(__half2 h) { return *reinterpret_cast<uint32_t*>(&h); }
__device__ __forceinline__ __half2 u2h(uint32_t u) { return *reinterpret_cast<__half2*>(&u); }
__device__ __forceinline__ unsigned long long gtime() { unsigned long long t; asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t)); return t; }

// per-item timestamps for the design probes only; compiled out of the shipped build
#ifdef H_STAMPS
#define STAMP(slot) if (tid == 0) p.stamps[(size_t)item * 8 + (slot)] = gtime();
#else
#define STAMP(slot)
#endif

template <int CC, int WW>
__global__ void __launch_bounds__(NTH, 1) h_kernel(const __grid_constant__ HP p) {
  constexpr int HW = WW * WW, C4 = 4 * CC, MT1 = C4 / 128, MT2 = CC / 128, NKB1 = CC / 64;
  constexpr int HWP = (WW == 7) ? 64 : 256, LOGHWP = (WW == 7) ? 6 : 8, IPT2 = (WW == 7) ? 2 : 1;
  constexpr int HWR = (HW + 7) & ~7, NCK = HWR / 8;
  extern __shared__ __align__(16) uint8_t smraw[];
  const int tid = threadIdx.x;
  const int warp = __shfl_sync(0xffffffffu, tid >> 5, 0), lane = tid & 31;
  uint8_t* sm = (uint8_t*)(((uintptr_t)smraw + 1023) & ~(uintptr_t)1023);
  uint8_t* ring = sm;
  const uint32_t ringa = smem_u32(ring);
  float* s_mu = (float*)(sm + RING);
  float* s_rs = s_mu + 256;
  float* s_u = s_rs + 256;
  float* s_c1 = s_u + 128;
  float* s_gw = s_c1 + 128;
  float* s_ss = s_gw + 128;  // [4][128]
  float* s_q = s_ss + 512;   // [4][128]
  float* s_inv = s_q + 512;  // [8]
  uint64_t* bars = (uint64_t*)(s_inv + 8);
  volatile uint32_t* s_misc = (volatile uint32_t*)(bars + 16);
  const uint32_t bar_full = smem_u32(bars), bar_empty = bar_full + 8 * NST, bar_acc = bar_full + 16 * NST, bar_conv = bar_acc + 8;
  if (tid == 0) {
    for (int i = 0; i < NST; i++) { mbar_init(bar_full + 8 * i, 1); mbar_init(bar_empty + 8 * i, 1); }
    mbar_init(bar_acc, 1); mbar_init(bar_conv, 1);
    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
  }
  if (warp == 0) {
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], 512;" ::"r"(smem_u32((void*)s_misc)) : "memory");
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;" ::: "memory");
  }
