  const uint32_t tmem = s_misc[0];
  uint32_t kit = 0, accph = 0, convph = 0, seen_conv = 0, seen_g1 = 0;
  bool w1ok = false, w2ok = false;
  int item = blockIdx.x;  // the first item is static; later ones come from the atomic head (claimed one item ahead)
  while (item < p.n_total) {
    int nxt = 0;
    if (tid == 0) nxt = (int)gridDim.x + (int)atomicAdd(p.ctr + CT_HEAD, 1u);
#ifdef H_STAMPS
    if (tid == 0) p.stamps[(size_t)item * 8 + 3] = blockIdx.x;
#endif
    STAMP(0)
    if (item < p.o_conv) {
      // ---- W1 unit: W1' = fp16(W1*lnw), u1 = rowsum(W1'), c1 = W1.lnb + b1 (contiguous row block, loads first)
      constexpr int R4 = CC / 4;
      const int u = item;
      const int rpu = (C4 + p.nW - 1) / p.nW, r0 = u * rpu, r1 = min(C4, r0 + rpu);
      const int nr = max(r1 - r0, 0);
      float* s_red = (float*)ring;
      if (tid < 64) s_red[tid] = 0.f;
      if (u == 0 && tid < p.B) p.gsum[tid] = 0.f;
      __syncthreads();
      const int nf = nr * R4;
      const float4* src4 = (const float4*)(p.w1 + (size_t)r0 * CC);
      constexpr int JB = 8;
      for (int base = 0; base < nf; base += NTH * JB) {
        float4 wv[JB], lw[JB], lb[JB];
#pragma unroll
        for (int j = 0; j < JB; j++) {
          const int f = base + tid + NTH * j;
